async function pcSaveMenuItem(id){const name=pcText($('pc_m_name').value),code=pcText($('pc_m_code').value),category=pcText($('pc_m_category').value);if(!name)return toast('نام آیتم الزامی است',true);if(code&&pricingState.menuItems.some(x=>x.code===code&&x.id!==id))return toast('کد آیتم تکراری است',true);const o={code:code||pcUid('ITEM',pricingState.menuItems),name,category:category||'سایر',currentPriceToman:pcNum($('pc_m_price').value),customTargetCostPercent:pcClamp($('pc_m_custom_target').value,0,100),manualCostToman:pcNum($('pc_m_manual_cost').value),manualCostEnabled:$('pc_m_manual_enabled').value==='true',status:$('pc_m_status').value,unit:$('pc_m_unit')?.value||'عدد',siteStatus:$('pc_m_site_status')?.value||'غیرفعال',notes:$('pc_m_notes').value};if(!pricingState.lists.menuCategories.includes(o.category)){pricingState.lists.menuCategories.push(o.category);pricingState.settings.categoryTargets[o.category]=35}if(id)Object.assign(pcMenu(id),o);else pricingState.menuItems.push({id:pcUid('MENU',pricingState.menuItems),...o,lastPriceChangeAt:null});await pcCommit(id?'ویرایش آیتم منو':'افزودن آیتم منو')}
function pcIngredientPreview(){
 const target=$('pc_i_yield_preview');if(!target)return;
 const ingredient={purchaseUnit:$('pc_i_purchase_unit')?.value,recipeUnit:$('pc_i_recipe_unit')?.value,packageQuantity:$('pc_i_pack_qty')?.value,lastPurchasePriceToman:$('pc_i_price')?.value,wastePercent:$('pc_i_waste')?.value};
 const m=pcIngredientMath(ingredient),u=ingredient.recipeUnit||'واحد';
 target.textContent=m.netUsableQuantity===null?'ناقص: مقدار ناخالص، واحدها و درصد افت معتبر وارد کنید.':'از '+pcFmt(m.packageQuantity,3)+' '+u+' خرید، حدود '+pcFmt(m.netUsableQuantity,3)+' '+u+' قابل‌مصرف است. هزینه مؤثر هر '+u+': '+(m.netUsableUnitCost===null?'ناقص؛ قیمت خرید وارد نشده':pcFmt(pcDisplayUnitCost(m.netUsableUnitCost))+' تومان؛ نمایش رو به بالا تا هزار تومان، محاسبه با مبلغ دقیق');
}
